import React, { useMemo, useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { useTranslation } from '@/contexts/LanguageContext';
import { useStudentClasses } from '@/hooks/useClasses';
import { apiService } from '@/services/api';
import { useQuery } from '@tanstack/react-query';
import type { AttendanceRecord, StudentClass, MeetingSchedule } from '@/types';
import { extractString, extractDate } from '@/utils/sqlNull';
import type { SqlNullString } from '@/types';
import { PageHeader, LoadingSpinner, Card, EmptyState } from '@/components/ui';
import { CheckCircle, XCircle, Clock, AlertCircle, ClockAlert, Minus } from 'lucide-react';

interface CourseAttendanceData {
  course: StudentClass;
  meetings: Array<{
    id: number;
    topik?: string;
    tgl_pertemuan: string;
    pertemuan_ke: number;
    attendance?: AttendanceRecord;
  }>;
  stats: {
    totalMeetings: number;
    attended: number;
    excused: number;
    sick: number;
    late: number;
    substitute: number;
    absent: number;
    attendancePercentage: number;
  };
}

const StudentAttendance: React.FC = () => {
  const { user } = useAuth();
  const { t } = useTranslation();
  const [selectedSemester, setSelectedSemester] = useState<string>('');

  // Fetch student classes
  const { data: studentClasses = [], isLoading: loadingClasses } = useStudentClasses(
    user?.studentId,
    selectedSemester ? { semester: selectedSemester } : undefined
  );

  // Fetch all meetings for student's classes
  const classIds = useMemo(() => studentClasses.map(c => c.kelas_id).filter((id): id is number => id !== undefined), [studentClasses]);

  const meetingsQueries = useQuery({
    queryKey: ['student-meetings', classIds],
    queryFn: async () => {
      if (classIds.length === 0) return {};

      const result: Record<number, MeetingSchedule[]> = {};

      await Promise.all(
        classIds.map(async (classId: number) => {
          try {
            const meetings = await apiService.getMeetingsByClass(classId);
            result[classId] = meetings;
          } catch (error) {
            console.error(`Failed to fetch meetings for class ${classId}:`, error);
            result[classId] = [];
          }
        })
      );

      return result;
    },
    enabled: classIds.length > 0,
  });

  // Fetch attendances for all meetings
  const meetingIds = useMemo(() => {
    if (!meetingsQueries.data) return [];
    return Object.values(meetingsQueries.data).flat().map(m => m.id);
  }, [meetingsQueries.data]);

  const attendancesQuery = useQuery({
    queryKey: ['student-all-attendances', meetingIds],
    queryFn: async () => {
      if (meetingIds.length === 0) return {};

      const result: Record<number, AttendanceRecord> = {};

      await Promise.all(
        meetingIds.map(async (meetingId) => {
          try {
            const attendances = await apiService.getMeetingAttendances(meetingId);
            const studentAttendance = attendances.find(a => a.nim === user?.studentId);
            if (studentAttendance) {
              result[meetingId] = studentAttendance;
            }
          } catch (error) {
            console.error(`Failed to fetch attendances for meeting ${meetingId}:`, error);
          }
        })
      );

      return result;
    },
    enabled: meetingIds.length > 0,
  });

  // Process data into course attendance groups with stats
  const courseAttendanceData = useMemo(() => {
    if (!meetingsQueries.data || !studentClasses.length) return [];

    return studentClasses
      .map((course) => {
        const meetings = (course.kelas_id !== undefined ? meetingsQueries.data?.[course.kelas_id] || [] : []).sort((a: MeetingSchedule, b: MeetingSchedule) => (a.pertemuan_ke || 0) - (b.pertemuan_ke || 0));

        const courseData: CourseAttendanceData = {
          course,
          meetings: meetings.map((m: MeetingSchedule) => ({
            id: m.id,
            topik: extractString(m.topik as string | SqlNullString),
            tgl_pertemuan: typeof m.tgl_pertemuan === 'string' ? m.tgl_pertemuan : m.tgl_pertemuan?.Time || '',
            pertemuan_ke: m.pertemuan_ke,
            attendance: attendancesQuery.data?.[m.id],
          })),
          stats: {
            totalMeetings: meetings.length,
            attended: 0,
            excused: 0,
            sick: 0,
            late: 0,
            substitute: 0,
            absent: 0,
            attendancePercentage: 0,
          },
        };

        // Calculate stats
        meetings.forEach((m: MeetingSchedule) => {
          const attendance = attendancesQuery.data?.[m.id];
          if (attendance) {
            const status = extractString(attendance.status_kehadiran as string | SqlNullString)?.toLowerCase();
            switch (status) {
              case 'hadir':
              case 'present':
                courseData.stats.attended++;
                break;
              case 'izin':
              case 'excused':
                courseData.stats.excused++;
                break;
              case 'sakit':
              case 'sick':
                courseData.stats.sick++;
                break;
              case 'terlambat':
              case 'late':
                courseData.stats.late++;
                break;
              case 'pengganti':
              case 'substitute':
                courseData.stats.substitute++;
                break;
              case 'alpa':
              case 'alfa':
              case 'absent':
                courseData.stats.absent++;
                break;
            }
          }
        });

        if (courseData.stats.totalMeetings > 0) {
          const presentMeetings = courseData.stats.attended + courseData.stats.late + courseData.stats.substitute;
          courseData.stats.attendancePercentage = Math.round((presentMeetings / courseData.stats.totalMeetings) * 100);
        }

        return courseData;
      })
      .sort((a, b) => extractString(a.course.kode_mk || '').localeCompare(extractString(b.course.kode_mk || '')));
  }, [studentClasses, meetingsQueries.data, attendancesQuery.data, user?.studentId]);

  // Extract unique semesters for filter
  const semesters = useMemo(() => {
    const semesterSet = new Set<string>();
    studentClasses.forEach(course => {
      const semester = course.semester;
      if (semester) semesterSet.add(semester);
    });
    return Array.from(semesterSet).sort().reverse();
  }, [studentClasses]);

  // Auto-select first semester if not selected
  React.useEffect(() => {
    if (!selectedSemester && semesters.length > 0) {
      setSelectedSemester(semesters[0]);
    }
  }, [semesters, selectedSemester]);

  const isLoading = loadingClasses || meetingsQueries.isLoading || attendancesQuery.isLoading;

  const getStatusIcon = (status: string) => {
    switch (status?.toLowerCase()) {
      case 'hadir':
      case 'present':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'izin':
      case 'excused':
        return <Clock className="h-4 w-4 text-blue-600" />;
      case 'sakit':
      case 'sick':
        return <AlertCircle className="h-4 w-4 text-yellow-600" />;
      case 'terlambat':
      case 'late':
        return <ClockAlert className="h-4 w-4 text-orange-600" />;
      case 'pengganti':
      case 'substitute':
        return <CheckCircle className="h-4 w-4 text-purple-600" />;
      case 'alpa':
      case 'alfa':
      case 'absent':
        return <XCircle className="h-4 w-4 text-red-600" />;
      default:
        return <Minus className="h-4 w-4 text-gray-300" />;
    }
  };

  const getAttendanceColorForPercentage = (percentage: number): string => {
    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  if (isLoading) {
    return (
      <div className="p-6 space-y-6">
        <PageHeader title="Attendance Record" />
        <div className="flex justify-center items-center h-96">
          <LoadingSpinner />
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <PageHeader title={t('student.attendanceRecord')} subtitle={t('student.viewAttendanceDesc')} />

      {/* Semester Filter */}
      {semesters.length > 1 && (
        <Card>
          <div className="flex items-center gap-4">
            <label htmlFor="semester-filter" className="font-medium text-gray-700">
              Semester:
            </label>
            <select
              id="semester-filter"
              value={selectedSemester}
              onChange={(e) => setSelectedSemester(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
            >
              {semesters.map((sem) => (
                <option key={sem} value={sem}>
                  {sem}
                </option>
              ))}
            </select>
          </div>
        </Card>
      )}

      {/* Course Attendance Tables - Compact Transposed Layout */}
      {courseAttendanceData.length === 0 ? (
        <EmptyState
          title={t('studentAttendance.noCourses')}
          description={t('studentAttendance.noCoursesDesc')}
        />
      ) : (
        <div className="space-y-3">
          {courseAttendanceData.map((courseData) => (
            <Card key={courseData.course.kelas_id} className="p-0 overflow-hidden">
              {/* Course Info and Summary - Single Compact Row */}
              <div className="bg-gradient-to-r from-primary-50 to-secondary-50 px-4 py-3 border-b border-gray-200">
                <div className="flex justify-between items-center gap-4">
                  <div className="flex-1">
                    <h3 className="font-semibold text-gray-900">
                      {extractString(courseData.course.kode_mk || '')} - {extractString(courseData.course.nama_mk || '')}
                    </h3>
                    <p className="text-xs text-gray-600">
                      {extractString(courseData.course.nama_kelas || '')}
                    </p>
                  </div>
                  
                  {/* Compact Stats */}
                  <div className="flex items-center gap-2 text-xs">
                    <div className="text-center">
                      <div className={`font-bold text-lg ${getAttendanceColorForPercentage(courseData.stats.attendancePercentage)}`}>
                        {courseData.stats.attendancePercentage}%
                      </div>
                    </div>
                    <div className="h-8 w-px bg-gray-300"></div>
                    <div className="flex gap-2">
                      <span className="bg-green-100 text-green-700 px-2 py-1 rounded text-xs font-medium">{courseData.stats.attended}</span>
                      <span className="bg-orange-100 text-orange-700 px-2 py-1 rounded text-xs font-medium">{courseData.stats.late}</span>
                      <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded text-xs font-medium">{courseData.stats.excused}</span>
                      <span className="bg-yellow-100 text-yellow-700 px-2 py-1 rounded text-xs font-medium">{courseData.stats.sick}</span>
                      <span className="bg-purple-100 text-purple-700 px-2 py-1 rounded text-xs font-medium">{courseData.stats.substitute}</span>
                      <span className="bg-red-100 text-red-700 px-2 py-1 rounded text-xs font-medium">{courseData.stats.absent}</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Attendance Grid - Weeks as Columns */}
              {courseData.meetings.length === 0 ? (
                <div className="p-4 text-center text-sm text-gray-500">
                  {t('studentAttendance.noMeetings')}
                </div>
              ) : (
                <div className="p-4">
                  <div className="flex gap-2 flex-wrap items-start">
                    {/* Legend and total info */}
                    <div className="text-xs text-gray-600 mb-2 w-full">
                      <div className="flex gap-3 flex-wrap">
                        <div className="flex items-center gap-1">
                          <CheckCircle className="h-3.5 w-3.5 text-green-600" />
                          <span>{t('studentAttendance.present')}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <ClockAlert className="h-3.5 w-3.5 text-orange-600" />
                          <span>{t('studentAttendance.late')}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Clock className="h-3.5 w-3.5 text-blue-600" />
                          <span>{t('studentAttendance.excused')}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <AlertCircle className="h-3.5 w-3.5 text-yellow-600" />
                          <span>{t('studentAttendance.sick')}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <CheckCircle className="h-3.5 w-3.5 text-purple-600" />
                          <span>{t('studentAttendance.substitute')}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <XCircle className="h-3.5 w-3.5 text-red-600" />
                          <span>{t('studentAttendance.absent')}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Minus className="h-3.5 w-3.5 text-gray-400" />
                          <span>{t('studentAttendance.notMarked')}</span>
                        </div>
                      </div>
                    </div>

                    {/* Week columns with attendance status icons */}
                    <div className="flex gap-1 flex-wrap">
                      {courseData.meetings.map((meeting) => {
                        const attendance = meeting.attendance;
                        const status = attendance ? extractString(attendance.status_kehadiran as string | SqlNullString) : undefined;
                        const meetingDate = extractDate(meeting.tgl_pertemuan);
                        const dateStr = meetingDate ? meetingDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';

                        return (
                          <div
                            key={meeting.id}
                            className="flex flex-col items-center gap-1 p-2 rounded border border-gray-200 hover:bg-gray-50 transition-colors cursor-help"
                            title={`Week ${meeting.pertemuan_ke} - ${dateStr}${meeting.topik ? ` - ${extractString(meeting.topik as string | SqlNullString)}` : ''}`}
                          >
                            <div className="text-xs font-semibold text-gray-600">W{meeting.pertemuan_ke}</div>
                            <div className="flex justify-center h-6">
                              {status ? (
                                getStatusIcon(status)
                              ) : (
                                <Minus className="h-5 w-5 text-gray-300" />
                              )}
                            </div>
                            <div className="text-xs text-gray-500 text-center leading-tight max-w-12 break-words">
                              {dateStr}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              )}
            </Card>
          ))}
        </div>
      )}
    </div>
  );
};

export default StudentAttendance;
